```java
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.function.BiFunction;
import java.util.function.Predicate;

public class LambdaSyntaxDemo {
    public static void main(String[] args) {
        List<String> names = Arrays.asList("Charlie", "Alice", "Bob");

        Comparator<String> anonymous = new Comparator<String>() {
            @Override
            public int compare(String a, String b) {
                return a.compareTo(b);
            }
        };
        Collections.sort(names, anonymous);

        Collections.sort(names, (a, b) -> a.compareTo(b));
        Collections.sort(names, String::compareTo);

        Runnable noParameters = () -> System.out.println("no parameters");
        Predicate<String> longName = s -> s.length() > 5;
        BiFunction<Integer, Integer, Integer> add = (a, b) -> a + b;
        Runnable block = () -> {
            System.out.println("step 1");
            System.out.println("step 2");
        };

        noParameters.run();
        System.out.println(longName.test("Charlie"));
        System.out.println(add.apply(2, 3));
        block.run();
    }
}
```

The anonymous Comparator, lambda, and method reference express the same sort order. The remaining lines show the main lambda syntax shapes with real target types.

```java
import java.util.function.Function;

public class EffectivelyFinalDemo {
    void demo() {
        String greeting = "Hello";
        Runnable print = () -> System.out.println(greeting);

        final int multiplier = 3;
        Function<Integer, Integer> triple = x -> x * multiplier;

        int count = 0;
        count++;
        // Runnable broken = () -> System.out.println(count); // does not compile

        int[] mutableCount = {0};
        Runnable increment = () -> mutableCount[0]++; // legal, but mutable
        increment.run();
    }
}
```

The array example compiles because the captured reference is not reassigned; its array contents can still change. That is not a thread-safety technique. Concurrent updates would need an appropriate atomic or synchronised design.

```java
public class LambdaAccessDemo {
    private String name = "Alice";
    private static int callCount = 0;

    void showAccess() {
        String local = "local"; // captured and effectively final

        Runnable task = () -> {
            System.out.println(local);
            // local = "changed"; // does not compile

            name = "Bob";       // normal instance-field access
            callCount++;          // normal static-field access
        };
        task.run();
    }

    void showThis() {
        Runnable task = () -> System.out.println(this.name);
    }
}
```

The restriction applies to captured local variables and parameters. Field access follows normal Java rules. Legal field mutation can still race if tasks run concurrently.
